import { spawn } from "node:child_process";
import {
  access,
  lstat,
  mkdir,
  mkdtemp,
  rename,
  rm,
  rmdir,
  writeFile,
} from "node:fs/promises";
import { constants } from "node:fs";
import { createRequire } from "node:module";
import { basename, dirname, join, resolve } from "node:path";
import { chromium } from "playwright-core";

const require = createRequire(import.meta.url);
const cli = join(
  dirname(require.resolve("playwright-core/package.json")),
  "cli.js",
);
const ownedProfiles = new WeakMap();
const identity = (entry) =>
  entry.isDirectory() ? `${entry.dev}:${entry.ino}:${entry.birthtimeNs}` : null;

/** Create only a fresh run-owned profile. Never change an existing profile. */
export async function createRunOwnedBrowserProfile(directory) {
  directory = resolve(directory);
  await mkdir(directory, { mode: 0o700 });
  const entry = await lstat(directory, { bigint: true });
  const parent = await lstat(dirname(directory), { bigint: true });
  const defaults = join(directory, "Default");
  await mkdir(defaults, { mode: 0o700 });
  // Browser-owned breach dialogs are outside the page input/screenshot surface.
  // Test credentials must not start Chrome's separate password-check workflow.
  await writeFile(
    join(defaults, "Preferences"),
    JSON.stringify({ profile: { password_manager_leak_detection: false } }),
    { mode: 0o600, flag: "wx" },
  );
  const owner = Object.freeze({});
  ownedProfiles.set(owner, {
    directory,
    entry: identity(entry),
    parent: identity(parent),
  });
  return owner;
}

/** Retire only the exact fresh directory after verified browser cleanup. */
export async function retireRunOwnedBrowserProfile(
  owner,
  { cleanupVerified, diagnosticConsumer } = {},
) {
  const profile = ownedProfiles.get(owner);
  const retained = (reason, extra = {}) => ({
    status: "retained",
    reason,
    ...extra,
  });
  if (!profile?.entry || !profile.parent)
    return retained("ownership-unverified");
  if (diagnosticConsumer !== undefined) profile.diagnosticConsumer = true;
  if (cleanupVerified !== true) return retained("cleanup-unverified");
  // Any supplied consumer prevents deletion, including a malformed declaration.
  // Later omission cannot prove that a previously named consumer has finished.
  if (profile.diagnosticConsumer) return retained("diagnostic-consumer");
  const { directory, entry, parent } = profile;
  let holding;
  try {
    if (
      identity(await lstat(dirname(directory), { bigint: true })) !== parent ||
      identity(await lstat(directory, { bigint: true })) !== entry
    )
      return retained("identity-changed");
    // Move into a fresh private container, then recheck the moved identity. A
    // replacement at the old pathname can never become the recursive target.
    holding = await mkdtemp(join(dirname(directory), ".profile-retire-"));
    const target = join(holding, "profile");
    await rename(directory, target);
    if (identity(await lstat(target, { bigint: true })) !== entry)
      return retained("identity-changed", { holding: basename(holding) });
    await rm(target, { recursive: true });
    ownedProfiles.delete(owner);
    return { status: "removed" };
  } catch (error) {
    return retained("retirement-unverified", {
      ...(holding ? { holding: basename(holding) } : {}),
      code: typeof error.code === "string" ? error.code : "UNKNOWN",
    });
  } finally {
    // rmdir removes an empty container only. Never recursively clear uncertain
    // contents after a failed identity check or a partial removal.
    if (holding) await rmdir(holding).catch(() => {});
  }
}

/** Browser provisioning only; scenario execution still calls Runner's Node API. */
export async function prepareBrowser({
  signal,
  timeoutMs = 600000,
  onOutput,
} = {}) {
  signal?.throwIfAborted();
  if (!Number.isSafeInteger(timeoutMs) || timeoutMs < 1)
    throw new TypeError(
      "Browser preparation timeout must be a positive integer.",
    );
  const executablePath = chromium.executablePath();
  const executableAlreadyPresent = await access(
    executablePath,
    constants.X_OK,
  ).then(
    () => true,
    () => false,
  );
  signal?.throwIfAborted();
  const timeout = AbortSignal.timeout(timeoutMs);
  const stop = signal ? AbortSignal.any([signal, timeout]) : timeout;
  // The pinned installer owns cache layout, cross-process locking, partial
  // downloads and revision checks. Even a cache hit runs that verification.
  // Full Chromium serves headed and new-headless consumers; no second shell.
  await new Promise((resolve, reject) => {
    const child = spawn(
      process.execPath,
      [cli, "install", "chromium", "--no-shell"],
      {
        detached: process.platform !== "win32",
        // Provisioning gets ordinary OS, proxy and Playwright installer settings,
        // not the host's model credentials or arbitrary runtime options.
        env: Object.fromEntries(
          [
            "HOME",
            "PATH",
            "TMPDIR",
            "TMP",
            "TEMP",
            "SystemRoot",
            "LOCALAPPDATA",
            "USERPROFILE",
            "XDG_CACHE_HOME",
            "HTTP_PROXY",
            "HTTPS_PROXY",
            "ALL_PROXY",
            "NO_PROXY",
            "http_proxy",
            "https_proxy",
            "all_proxy",
            "no_proxy",
            "NODE_EXTRA_CA_CERTS",
            "PLAYWRIGHT_BROWSERS_PATH",
            "PLAYWRIGHT_DOWNLOAD_HOST",
            "PLAYWRIGHT_CHROMIUM_DOWNLOAD_HOST",
            "PLAYWRIGHT_DOWNLOAD_CONNECTION_TIMEOUT",
            "PLAYWRIGHT_SKIP_BROWSER_GC",
          ]
            .filter((name) => process.env[name] !== undefined)
            .map((name) => [name, process.env[name]]),
        ),
        stdio: ["ignore", "pipe", "pipe"],
      },
    );
    let escalation, failure;
    const kill = (signalName) => {
      if (!child.pid) return;
      try {
        if (process.platform === "win32") child.kill(signalName);
        else process.kill(-child.pid, signalName);
      } catch (error) {
        if (error.code !== "ESRCH") failure = error;
      }
    };
    const abort = () => {
      kill("SIGTERM");
      escalation = setTimeout(() => kill("SIGKILL"), 2000);
      escalation.unref();
    };
    const output = (bytes) => {
      try {
        onOutput?.(bytes.toString());
      } catch {
        /* Observer only. */
      }
    };
    child.stdout.on("data", output);
    child.stderr.on("data", output);
    child.once("error", (error) => {
      failure = error;
    });
    child.once("close", (code) => {
      stop.removeEventListener("abort", abort);
      clearTimeout(escalation);
      if (stop.aborted) {
        // Terminate only this installer's process group, including a downloader
        // that outlived its parent. Never enumerate or kill other host children.
        kill("SIGKILL");
        reject(failure ?? stop.reason);
      } else if (failure) reject(failure);
      else if (code !== 0)
        reject(
          new Error(
            `Chromium preparation failed (installer exit ${code}); no browser or provider request was started.`,
          ),
        );
      else resolve();
    });
    stop.addEventListener("abort", abort, { once: true });
    if (stop.aborted) abort();
  });
  stop.throwIfAborted();
  await access(executablePath, constants.X_OK);
  return {
    browser: "chromium",
    playwrightVersion: require("playwright-core/package.json").version,
    executablePath,
    executableAlreadyPresent,
  };
}
